// Des: CLI: show the effective settings for a host, or check every site rule
// Flo: site --check > validate groups, sites, paths > site <host or url> > merge layers > one line per changed key with its source
// I/O: Ctx (caller) > text or JSON lines; exit 0 ok, 2 bad usage, config error otherwise
// ===================================================================
const std = @import("std"); const cx = @import("ct-ctrl-ctxz.zig"); const site = @import("cf-site-rule.zig"); const urln = @import("ut-urlz-norm.zig");
const Line = struct { keyz: []const u8, valu: []const u8, from: []const u8 };
const Repo = struct { host: []const u8, path: []const u8, rule: []const u8, list: []const Line };
fn countOf(valu: ?std.json.Value) usize { const vz = valu orelse return 0; return switch (vz) { .array => |arr| arr.items.len, .object => |obj| obj.count(), else => 0 }; }
pub fn runSite(ctx: *const cx.Ctx) !u8 { if (ctx.args.chek) { var diag: site.Diag = .{}; site.siteChek(ctx.conf, &diag) catch { try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "site rules INVALID: {s}", .{diag.text})); return error.BadConfig; }; try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "site rules ok: {d} group(s), {d} site(s)", .{ countOf(ctx.conf.grup_rule_mapz), countOf(ctx.conf.site_rule_list) })); return 0; } if (ctx.args.urlz.len == 0) return error.BadUsage; var host: []const u8 = ctx.args.urlz; var path: []const u8 = "/"; if (std.mem.find(u8, ctx.args.urlz, "://") != null) { const part = urln.urlSplit(ctx.args.urlz) catch return error.BadUsage; host = part.host; path = part.path; } var srcs: std.ArrayList(site.Srcz) = .empty; const merged = try site.siteExpl(ctx.allo, ctx.conf, host, path, &srcs); var list: std.ArrayList(Line) = .empty; var rule: []const u8 = "none (global settings only)"; for (srcs.items) |item| { var seen = false; for (list.items) |prev| { if (std.mem.eql(u8, prev.keyz, item.keyz)) seen = true; } if (seen) continue; var last = item.from; for (srcs.items) |later| { if (std.mem.eql(u8, later.keyz, item.keyz)) last = later.from; } try list.append(ctx.allo, .{ .keyz = item.keyz, .valu = try site.valText(ctx.allo, merged, item.keyz), .from = last }); if (std.mem.startsWith(u8, item.from, "site ")) rule = item.from; } const repo: Repo = .{ .host = host, .path = path, .rule = rule, .list = list.items }; var plain: std.ArrayList(u8) = .empty; try plain.print(ctx.allo, "host {s} path {s} | rule: {s}\n", .{ host, path, rule }); for (list.items) |ln| try plain.print(ctx.allo, "  {s} = {s}   ({s})\n", .{ ln.keyz, ln.valu, ln.from }); try cx.outz(ctx, try cx.jsonOr(ctx, repo, std.mem.trimEnd(u8, plain.items, "\n"))); return 0; }
